(6396827, 947864, 65234, '<td valign="top">I see that bit of red under the tail!  Catbirds with their raucous calls just arrived here a few weeks ago.  They''re entertaining birds :-)  "Yours" is nicely captured and the green bokeh makes him stand out well.</td>', 'I see that bit of red under the tail!  Catbirds with their raucous calls just arrived here a few weeks ago.  They''re entertaining birds :-)  "Yours" is nicely captured and the green bokeh makes him stand out well.', '2011-04-27 09:42:18.000000', NULL, 1),
(6396829, 947847, 65234, '<td valign="top">It''s a thistle!  Quite popular with the pollinating set.  I like the soft colors and the repetition of shapes in the bokeh.</td>', 'It''s a thistle!  Quite popular with the pollinating set.  I like the soft colors and the repetition of shapes in the bokeh.', '2011-04-27 09:43:14.000000', NULL, 1),
(6396833, 947793, 65234, '<td valign="top">My, what big eyes he has!  I particularly like the bit of texture in the bokeh on the right.</td>', 'My, what big eyes he has!  I particularly like the bit of texture in the bokeh on the right.', '2011-04-27 09:44:31.000000', NULL, 1),
