(6399001, 947204, 76335, '<td valign="top">Nice springtime colors. Vibrant smile. Like the twist of hair just off her left ear.</td>', 'Nice springtime colors. Vibrant smile. Like the twist of hair just off her left ear.', '2011-04-29 21:18:48.000000', NULL, 1),
(6399003, 947480, 76335, '<td valign="top">I like the converging lines in this.</td>', 'I like the converging lines in this.', '2011-04-29 21:19:13.000000', NULL, 1),
(6399004, 947224, 76335, '<td valign="top">Thick rich bokeh. Magical.</td>', 'Thick rich bokeh. Magical.', '2011-04-29 21:19:40.000000', NULL, 1),
(6399005, 947603, 76335, '<td valign="top">I do like the soft pastel colors and textures here. Nicely composed too.</td>', 'I do like the soft pastel colors and textures here. Nicely composed too.', '2011-04-29 21:20:01.000000', NULL, 1),
(6399008, 947944, 76335, '<td valign="top">I like the thirds-oriented composition. Effective in black and white.</td>', 'I like the thirds-oriented composition. Effective in black and white.', '2011-04-29 21:22:59.000000', NULL, 1),
(6399010, 947659, 76335, '<td valign="top">Something different. A softer early or late day light would have made this more appealing.</td>', 'Something different. A softer early or late day light would have made this more appealing.', '2011-04-29 21:23:41.000000', NULL, 1),
(6399011, 947947, 76335, '<td valign="top">I like how the flowers seem to go in and out of focus. As such, the whole image has a twinkling effect. Wish the frame were bigger.</td>', 'I like how the flowers seem to go in and out of focus. As such, the whole image has a twinkling effect. Wish the frame were bigger.', '2011-04-29 21:25:22.000000', NULL, 1),
(6399012, 947320, 76335, '<td valign="top">Nicely done. I like the bite taken out of that one petal on the right.</td>', 'Nicely done. I like the bite taken out of that one petal on the right.', '2011-04-29 21:25:51.000000', NULL, 1),
(6399013, 947544, 76335, '<td valign="top">The background green, so soft and subtle against all that brown, seems to foretell the coming of spring.</td>', 'The background green, so soft and subtle against all that brown, seems to foretell the coming of spring.', '2011-04-29 21:28:00.000000', NULL, 1),
(6399014, 947879, 76335, '<td valign="top">Beautiful bird, nicely captured.</td>', 'Beautiful bird, nicely captured.', '2011-04-29 21:28:20.000000', NULL, 1),
(6399016, 947917, 76335, '<td valign="top">The color is beautiful and really needs to fill the space. The frame is too much and only detracts.</td>', 'The color is beautiful and really needs to fill the space. The frame is too much and only detracts.', '2011-04-29 21:29:33.000000', NULL, 1),
(6399018, 947736, 76335, '<td valign="top">My favorite bug macro in this challenge so far. Crazy good light show.</td>', 'My favorite bug macro in this challenge so far. Crazy good light show.', '2011-04-29 21:31:28.000000', NULL, 1),
(6399019, 947838, 76335, '<td valign="top">I do like the arrangement of lines in this, accentuated by your tight framing.</td>', 'I do like the arrangement of lines in this, accentuated by your tight framing.', '2011-04-29 21:32:16.000000', NULL, 1),
(6399021, 947756, 58137, '<td valign="top">This is an awesome low fidelity photo!  I hope others can have the open mindedness to appreciate this too.</td>', 'This is an awesome low fidelity photo!  I hope others can have the open mindedness to appreciate this too.', '2011-04-29 21:34:03.000000', NULL, 1),
(6399022, 947882, 76335, '<td valign="top">Nice the way they seem to undulate their way to the surface.</td>', 'Nice the way they seem to undulate their way to the surface.', '2011-04-29 21:36:55.000000', NULL, 1),
