(6399024, 947844, 76335, '<td valign="top">Feels like I''m seeing through the eyes of a bug about to make a landing.</td>', 'Feels like I''m seeing through the eyes of a bug about to make a landing.', '2011-04-29 21:37:26.000000', NULL, 1),
