INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6402085, 947224, 19825, '<td valign="top">I love this shot -- I thought it should have ribboned. I would not have thought to plant the outcast among the purples. Nor would I thought of tilting the horizon slightly. Nice work.</td>', 'I love this shot -- I thought it should have ribboned. I would not have thought to plant the outcast among the purples. Nor would I thought of tilting the horizon slightly. Nice work.', '2011-05-02 17:01:01.000000', NULL, 0),
(6402089, 947569, 19825, '<td valign="top">This was a great capture that was one of my favorites in the challenge. The flower is striking and the bokeh is beautiful.</td>', 'This was a great capture that was one of my favorites in the challenge. The flower is striking and the bokeh is beautiful.', '2011-05-02 17:03:24.000000', NULL, 0),
(6402098, 947945, 19825, '<td valign="top">I think you were robbed. This should have placed much higher. There were a lot of flowers in this challenge but this one was one of the most striking. Nice one.</td>', 'I think you were robbed. This should have placed much higher. There were a lot of flowers in this challenge but this one was one of the most striking. Nice one.', '2011-05-02 17:07:42.000000', NULL, 0),
(6402106, 947603, 19825, '<td valign="top">I was going back through the Bokeh entries and had to comment on this one. I thought your image was particularly beautiful with great bokeh and very interesting composition. It was in my top 10. Nice shot.</td>', 'I was going back through the Bokeh entries and had to comment on this one. I thought your image was particularly beautiful with great bokeh and very interesting composition. It was in my top 10. Nice shot.', '2011-05-02 17:13:38.000000', NULL, 0),
(6402114, 947766, 41864, '<td valign="top">Beautiful, well done.</td>', 'Beautiful, well done.', '2011-05-02 17:19:38.000000', NULL, 0),
(6402121, 947838, 128809, '<td valign="top">I didn''t vote but understand your frustration at the low placing. I think, as you''ve guessed, it was possibly more to do with the subject not being that exciting, there''s not really anything to draw the viewer into the image and linger for longer. Better luck next time!</td>', 'I didn''t vote but understand your frustration at the low placing. I think, as you''ve guessed, it was possibly more to do with the subject not being that exciting, there''s not really anything to draw the viewer into the image and linger for longer. Better luck next time!', '2011-05-02 17:27:21.000000', NULL, 0),
(6402134, 947296, 48820, '<td valign="top">This is called a money plant or silver dollar plant, because the seed pod drys to a round transparent disk about the size of a silver dollar.  The small flower is beautiful.  Nice picture with good bokeh.<br/> <br/><a href="//en.wikipedia.org/wiki/Lunaria_annua" rel="nofollow" target="_blank">Lunaria annua</a><br/><br/><i>Message edited by author 2011-05-02 17:01:08.</i></td>', 'This is called a money plant or silver dollar plant, because the seed pod drys to a round transparent disk about the size of a silver dollar.  The small flower is beautiful.  Nice picture with good bokeh. Lunaria annua', '2011-05-02 17:39:14.000000', '2011-05-02 18:01:08.000000', 0),
(6402260, 947854, 11769, '<td valign="top">When the stomach is full and mind at peace it is time to stretch back and with eyes blurred glorify in the knowledge, that was one of those times to remember.</td>', 'When the stomach is full and mind at peace it is time to stretch back and with eyes blurred glorify in the knowledge, that was one of those times to remember.', '2011-05-02 19:22:56.000000', NULL, 0),
(6402269, 947943, 11769, '<td valign="top">Like pennies from heaven.</td>', 'Like pennies from heaven.', '2011-05-02 19:26:19.000000', NULL, 0),
(6402272, 947756, 11769, '<td valign="top">This is exquisite.</td>', 'This is exquisite.', '2011-05-02 19:37:39.000000', NULL, 0),
(6402273, 947931, 11769, '<td valign="top">Caught the beauty of spring. Love the color.</td>', 'Caught the beauty of spring. Love the color.', '2011-05-02 19:39:34.000000', NULL, 0),
(6402275, 947648, 11769, '<td valign="top">This is proof there are Cool Dudes out there.</td>', 'This is proof there are Cool Dudes out there.', '2011-05-02 19:42:08.000000', NULL, 0),
